for name in credential_names(tok) {
    if matches_any_pattern(&name, &cred_patterns) {
        findings.push(finding(
            "new_secret_or_credential_access",
            format!("the installation reads the credential '{name}'"),
            at.clone(),
            "TOOL_POLICY.installation_envelope.credential_patterns: the project authorises no new credential access to an installed tool".into(),
        ));
    }
}
for c in token_values(tok) {
    if let Some(h) = endpoint_host(&c) {
        endpoints.push((h, at.clone()));
        continue;
    }
    // AR75-F1: every non-flag candidate is resolved against the project boundary, not only one that
    // happens to contain a `/` -- a bare word such as an in-project symlink's own name escapes just as
    // effectively as an absolute path once the filesystem is consulted (`resolves_outside_project`),
    // and an inert bare word (a flag, a program name reused as an argument, `--version`) simply
    // resolves under the root and is dropped below with no finding.
    match resolves_outside_project(&p.root, &c) {
        Ok(true) => {
            findings.push(finding(
                "broader_filesystem_or_project_access",
                format!("the installation reaches '{c}', outside the project"),
                at.clone(),
                "the project root, as the path map (REPOSITORY_CONTRACT.yaml) scopes it"
                    .into(),
            ));
            continue;
        }
        Ok(false) => {}
        Err(reason) => {
            undetermined.push(format!(
                "{at} ('{c}'): {reason}; a candidate the OS cannot resolve is not classified as staying inside the project (OD-P2-05 clause 3)"
            ));
            continue;
        }
    }
    if secret_paths.iter().any(|g| crate::util::glob_match(g, &c)) {
        findings.push(finding(
            "new_secret_or_credential_access",
            format!("the installation reaches '{c}', a secret path"),
            at.clone(),
            "SECURITY_POLICY.secret_path_patterns".into(),
        ));
        continue;
    }
